import React from 'react';
import { t } from '../../i18n';
import './PlaysMenu.css';

const GAMES = [
  {
    id: 'first-letter',
    icon: '🔤',
    nameKey: 'gameFirstLetterName',
    descKey: 'gameFirstLetterDesc',
  },
];

function PlaysMenu({ onBack, uiLang, onStartGame }) {
  return (
    <div className="plays-menu-container">
      <div className="plays-menu-header">
        <button className="plays-menu-back" onClick={onBack}>
          {t('back', uiLang)}
        </button>
      </div>

      <h1 className="plays-menu-title">{t('menuPlays', uiLang)}</h1>

      <div className="plays-menu-grid">
        {GAMES.map((game) => (
          <div key={game.id} className="play-card">
            <div className="play-card__name">{t('firstLetterTitle', uiLang)}</div>
            <button
              className="play-card__btn"
              onClick={() => onStartGame && onStartGame(game.id)}
            >
              {t('playsStart', uiLang)}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default PlaysMenu;
