import React, { useState } from 'react';
import { t } from '../../../i18n';
import { resetPassword } from '../../../lib/userService';
import './ResetPasswordButton.css';

const ResetPasswordButton = ({ uiLang }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [oldPassword, setOldPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const toggleOpen = () => {
    setIsOpen((prev) => !prev);
    setError('');
    setSuccess('');
  };

  const handleSubmit = async () => {
    setError('');
    setSuccess('');

    if (!oldPassword || !newPassword) {
      setError(t('authFillAll', uiLang));
      return;
    }

    setIsLoading(true);
    try {
      await resetPassword(oldPassword, newPassword);
      setOldPassword('');
      setNewPassword('');
      setSuccess(t('resetPasswordSuccess', uiLang));
    } catch (err) {
      const msg = String(err?.message || '').toLowerCase();
      if (msg.includes('invalid_current_password') || msg.includes('invalid login credentials')) {
        setError(t('resetPasswordInvalidCurrent', uiLang));
      } else if (msg.includes('weak_password') || msg.includes('at least 6')) {
        setError(t('resetPasswordWeak', uiLang));
      } else {
        setError(t('resetPasswordFailed', uiLang));
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="reset-password-wrapper">
      <div className="menu-item reset-password-button" onClick={toggleOpen}>
        {t('menuResetPassword', uiLang)}
      </div>

      {isOpen && (
        <div className="reset-password-panel">
          <input
            type="password"
            className="reset-password-input"
            value={oldPassword}
            onChange={(e) => setOldPassword(e.target.value)}
            placeholder={t('resetPasswordCurrentPlaceholder', uiLang)}
            disabled={isLoading}
            autoComplete="current-password"
          />
          <input
            type="password"
            className="reset-password-input"
            value={newPassword}
            onChange={(e) => setNewPassword(e.target.value)}
            placeholder={t('resetPasswordNewPlaceholder', uiLang)}
            disabled={isLoading}
            autoComplete="new-password"
          />
          <button className="reset-password-submit" onClick={handleSubmit} disabled={isLoading}>
            {isLoading ? t('loginLoading', uiLang) : t('resetPasswordSubmit', uiLang)}
          </button>
          {error && <div className="reset-password-error">{error}</div>}
          {success && <div className="reset-password-success">{success}</div>}
        </div>
      )}
    </div>
  );
};

export default ResetPasswordButton;
