import React from 'react';
import { t } from '../../../i18n';
import './DeleteAccountButton.css';

const DeleteAccountButton = ({ onDeleteAccount, uiLang }) => {
  const handleClick = () => {
    if (!onDeleteAccount) return;
    if (window.confirm(t('deleteAccountConfirm', uiLang))) {
      onDeleteAccount();
    }
  };

  return (
    <div className="menu-item delete-account-button" onClick={handleClick}>
      {t('menuDeleteAccount', uiLang)}
    </div>
  );
};

export default DeleteAccountButton;
