export const loadAvailableLanguageIds = async (languageIds) => {
  const checks = languageIds.map(async (id) => {
    try {
      await import(
        /* webpackInclude: /Table_[A-Z]{2}\.json$/ */
        `../wordLibrary/Table_${id}.json`
      );
      return id;
    } catch (error) {
      return null;
    }
  });

  const results = await Promise.all(checks);
  return results.filter(Boolean);
};

export const loadLanguageTable = async (languageId) => {
  if (!languageId) return [];
  try {
    const data = await import(
      /* webpackInclude: /Table_[A-Z]{2}\.json$/ */
      `../wordLibrary/Table_${languageId}.json`
    );
    const tableKey = `Table_${languageId}`;
    const table = data?.[tableKey];
    return Array.isArray(table) ? table : [];
  } catch (error) {
    return [];
  }
};
