import React from 'react';
import { t } from '../../../i18n';
import './LogoutButton.css';

const LogoutButton = ({ onLogout, uiLang }) => {
  return (
    <div className="menu-item logout-button" onClick={onLogout}>
      {t('menuLogout', uiLang)}
    </div>
  );
};

export default LogoutButton;
