import React from 'react';
import { t } from '../../i18n';
import { getLanguageCssVars } from '../ColorsMap';
import './Story.css';

const Story = ({ onBack, uiLang, learningLang }) => {
  const themeVars = getLanguageCssVars(learningLang || uiLang || 'EN');

  return (
    <div className="story-container" style={themeVars}>
      <button className="story-back-button" onClick={onBack}>
        {t('back', uiLang)}
      </button>
      <div className="story-content">
        Тут будет история
      </div>
    </div>
  );
};

export default Story;
