import React, { useEffect, useMemo, useState } from 'react';
import { t } from '../../../i18n';
import { getLanguageCssVars } from '../../ColorsMap';
import './Dialogs.css';

const dialogsContext = require.context('../../../dialogsLibrary', true, /\.json$/);

const DIALOG_TRANSLATION_KEYS = {
	AtTheMarket: 'dialogThemeAtTheMarket',
	Family: 'dialogThemeFamily',
	InTheCity: 'dialogThemeInTheCity',
	Knowledge: 'dialogThemeKnowledge'
};

const DIALOG_ROLE_TRANSLATION_KEYS = {
	Cliente: 'dialogRoleCustomer',
	Vendedor: 'dialogRoleSeller',
	Turista: 'dialogRoleTourist',
	Residente: 'dialogRoleResident',
	Maks: 'dialogRoleMaks',
	Julia: 'dialogRoleJulia'
};

const normalizeDialogModule = (module) => module?.default ?? module;

const normalizeFormKey = (value) => {
	if (!value) return null;
	const lowered = value.toLowerCase();
	if (lowered.includes('informal')) return 'informal';
	if (lowered.includes('formal')) return 'formal';
	return null;
};

const parseDialogEntry = (key) => {
	const normalizedKey = key.replace(/^\.\//, '');
	const parts = normalizedKey.split('/');
	const folder = parts[0] || '';
	const fileName = parts[1] || '';
	const folderMatch = folder.match(/^dialogs_(.+)$/i);
	const folderLanguage = folderMatch ? folderMatch[1].toUpperCase() : null;
	const nameWithoutExt = fileName.replace(/\.json$/i, '');
	const nameParts = nameWithoutExt.split('_');
	const dialogName = nameParts[0] || null;
	const form = normalizeFormKey(nameWithoutExt);
	const fileLanguage = (nameParts[nameParts.length - 1] || '').toUpperCase();
	const language = folderLanguage || (fileLanguage ? fileLanguage : null);

	if (!dialogName || !language) return null;

	return {
		key,
		dialogName,
		form,
		language
	};
};

const DIALOG_INDEX = dialogsContext
	.keys()
	.map(parseDialogEntry)
	.filter(Boolean);

const getEntriesForLanguage = (languageId) => {
	if (!languageId) return [];
	const normalized = languageId.toUpperCase();
	return DIALOG_INDEX.filter(entry => entry.language === normalized);
};

export const listDialogsForLanguage = (languageId) => {
	const entries = getEntriesForLanguage(languageId);
	const unique = Array.from(new Set(entries.map(entry => entry.dialogName)));
	return unique.sort((a, b) => a.localeCompare(b));
};

export const listFormsForDialog = (languageId, dialogName) => {
	if (!dialogName) return [];
	const entries = getEntriesForLanguage(languageId)
		.filter(entry => entry.dialogName === dialogName);
	const forms = Array.from(new Set(entries.map(entry => entry.form).filter(Boolean)));
	return forms.sort();
};

export const getDialogData = (languageId, dialogName, form) => {
	if (!dialogName || !languageId) return null;
	const entries = getEntriesForLanguage(languageId)
		.filter(entry => entry.dialogName === dialogName);
	if (entries.length === 0) return null;

	const normalizedForm = normalizeFormKey(form);
	const entry = normalizedForm
		? entries.find(item => item.form === normalizedForm)
		: entries[0];

	if (!entry) return null;
	const module = dialogsContext(entry.key);
	const data = normalizeDialogModule(module);
	return Array.isArray(data) ? data : null;
};

export const getDialogRolesForDialog = (languageId, dialogName) => {
	if (!dialogName || !languageId) return [];
	const entries = getEntriesForLanguage(languageId)
		.filter(entry => entry.dialogName === dialogName);
	if (entries.length === 0) return [];

	const roles = entries.flatMap((entry) => {
		const module = dialogsContext(entry.key);
		const data = normalizeDialogModule(module);
		if (!Array.isArray(data)) return [];
		return data.map(row => row?.Person).filter(Boolean);
	});

	return Array.from(new Set(roles)).sort((a, b) => a.localeCompare(b));
};

export const getDialogRoles = (dialogData) => {
	if (!Array.isArray(dialogData)) return [];
	const roles = dialogData
		.map(row => row?.Person)
		.filter(Boolean);
	return Array.from(new Set(roles)).sort((a, b) => a.localeCompare(b));
};

const humanizeDialogName = (dialogName) => {
	if (!dialogName) return '';
	return dialogName
		.replace(/([a-z])([A-Z])/g, '$1 $2')
		.replace(/[_-]+/g, ' ')
		.trim();
};

export const getDialogDisplayName = (dialogName, uiLang) => {
	if (!dialogName) return '';
	const translationKey = DIALOG_TRANSLATION_KEYS[dialogName];
	return translationKey ? t(translationKey, uiLang) : humanizeDialogName(dialogName);
};

export const getDialogRoleDisplayName = (roleName, uiLang) => {
	if (!roleName) return '';
	const translationKey = DIALOG_ROLE_TRANSLATION_KEYS[roleName];
	return translationKey ? t(translationKey, uiLang) : roleName;
};

const BLANK_PLACEHOLDER = '____';

const buildLineParts = (row, difficulty) => {
	const isMedium = difficulty === 'medium';
	const isHard = difficulty === 'hard';
	const parts = [
		{ key: 'Start', blank: false },
		{ key: 'Lvl_3', blank: isHard },
		{ key: 'Middle', blank: false },
		{ key: 'Lvl_2', blank: isMedium || isHard },
		{ key: 'End', blank: false }
	];

	return parts
		.map(({ key, blank }) => {
			const value = row?.[key];
			const hasValue = typeof value === 'string' ? value.trim() !== '' : !!value;
			if (!hasValue) return null;
			return {
				key,
				text: value,
				isHidden: blank
			};
		})
		.filter(Boolean);
};

export const buildDialogLines = (dialogData, difficulty) => {
	if (!Array.isArray(dialogData)) return [];
	return dialogData
		.map((row) => {
			const parts = buildLineParts(row, difficulty || 'easy');
			return {
				id: row?.ID,
				person: row?.Person || '',
				parts,
				hasHiddenParts: parts.some((part) => part.isHidden)
			};
		})
		.filter(line => line.parts.length > 0);
};

export const Dialogs = ({ onBack, uiLang, settings }) => {
	const languageId = settings?.languageId || 'ES';
	const dialogName = settings?.dialogName || '';
	const form = settings?.form || 'formal';
	const difficulty = settings?.difficulty || 'easy';
	const role = settings?.role || '';
	const themeVars = getLanguageCssVars(languageId);

	const dialogData = useMemo(
		() => getDialogData(languageId, dialogName, form),
		[languageId, dialogName, form]
	);
	const lines = useMemo(
		() => buildDialogLines(dialogData, difficulty),
		[dialogData, difficulty]
	);
	const primaryRightRole = useMemo(() => {
		if (role) return role;
		const orderedRoles = [];
		lines.forEach((line) => {
			if (line.person && !orderedRoles.includes(line.person)) {
				orderedRoles.push(line.person);
			}
		});
		return orderedRoles[1] || orderedRoles[0] || '';
	}, [lines, role]);
	const [visibleCount, setVisibleCount] = useState(1);
	const [revealedLineIds, setRevealedLineIds] = useState(() => new Set());

	useEffect(() => {
		setVisibleCount(1);
		setRevealedLineIds(new Set());
	}, [dialogName, form, difficulty, role, lines.length]);

	const handleAdvance = () => {
		setVisibleCount(prev => Math.min(prev + 1, lines.length));
	};

	const handleLineClick = (event, lineId, hasHiddenParts) => {
		event.stopPropagation();
		if (!hasHiddenParts) return;
		setRevealedLineIds((prev) => {
			if (prev.has(lineId)) return prev;
			const next = new Set(prev);
			next.add(lineId);
			return next;
		});
	};

	if (!dialogName) {
		return (
			<div className="dialogs-view-container" style={themeVars}>
				<button
					className="dialogs-view-back-button"
					onClick={(event) => {
						event.stopPropagation();
						onBack();
					}}
				>
					{t('back', uiLang)}
				</button>
				<h1 className="dialogs-view-title">{t('dialogsTitle', uiLang)}</h1>
				<p className="dialogs-view-empty">{t('dialogsEmpty', uiLang)}</p>
			</div>
		);
	}

	return (
		<div className="dialogs-view-container" style={themeVars} onClick={handleAdvance}>
			<button
				className="dialogs-view-back-button"
				onClick={(event) => {
					event.stopPropagation();
					onBack();
				}}
			>
				{t('back', uiLang)}
			</button>
			<div className="dialogs-view-header">
				<h1 className="dialogs-view-title">{getDialogDisplayName(dialogName, uiLang)}</h1>
				<span className="dialogs-view-subtitle">
					{form === 'formal' ? t('dialogsFormFormal', uiLang) : t('dialogsFormInformal', uiLang)}
				</span>
			</div>
			<div className="dialogs-view-lines">
				{lines.length === 0 && (
					<p className="dialogs-view-empty">{t('dialogsEmpty', uiLang)}</p>
				)}
				{lines.slice(0, visibleCount).map((line, index) => {
					const isRevealed = revealedLineIds.has(line.id);
					return (
						<div
							key={`${line.id}-${index}`}
							className={`dialogs-view-line ${line.person === primaryRightRole ? 'dialogs-view-line--right' : 'dialogs-view-line--left'} ${line.hasHiddenParts ? 'dialogs-view-line--masked' : ''}`}
							onClick={(event) => handleLineClick(event, line.id, line.hasHiddenParts)}
						>
							<span className="dialogs-view-person">{line.person}</span>
							<span className="dialogs-view-text">
								{line.parts.map((part, partIndex) => (
									<span key={`${line.id}-${part.key}-${partIndex}`}>
										{partIndex > 0 ? ' ' : ''}
										{part.isHidden && !isRevealed ? BLANK_PLACEHOLDER : part.text}
									</span>
								))}
							</span>
						</div>
					);
				})}
			</div>
			{lines.length > 0 && visibleCount < lines.length && (
				<div className="dialogs-view-hint">{t('dialogsTapToContinue', uiLang)}</div>
			)}
		</div>
	);
};

export default Dialogs;
