import MainMenu from './components/mainMenu/MainMenu';
import StartChoosingLanguages from './components/StartChoosingLanguages';
import Cards from './components/learning/cards/Cards';
import CardsMenu from './components/learning/cards/CardsMenu';
import DialogsMenu from './components/learning/dialogs/DialogsMenu';
import Dialogs from './components/learning/dialogs/Dialogs';
import Story from './components/story/Story';
import Stats from './components/stats/Stats';
import Grammar from './components/grammar/grammar';
import PlaysMenu from './components/plays/PlaysMenu';
import TheFirstLetterMenu from './components/plays/theFirstLetter/TheFirstLetterMenu';
import Login from './components/login/Login';
import { getLanguageCssVars } from './components/ColorsMap';
import LanguagesConnections from './wordLibrary/LanguagesConnections.json';
import WordsSection from './wordLibrary/wordsParams/WordsSection.json';
import { loadLanguageTable } from './utils/availableLanguages';
import { supabase } from './lib/supabase';
import {
  getUserSettings as getUserSettingsSvc,
  saveUserSettings as saveUserSettingsSvc,
  getUserTable as getUserTableSvc,
  saveUserTable as saveUserTableSvc,
  deleteAccount as deleteAccountSvc,
  logout as logoutSvc
} from './lib/userService';
import './index.css';
import { useState, useEffect } from 'react';

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [languages, setLanguages] = useState({
    native: null,
    learning: [],
  });
  const [showMainMenu, setShowMainMenu] = useState(false);
  const [cardsMenuMode, setCardsMenuMode] = useState(false);
  const [cardsMode, setCardsMode] = useState(false);
  const [cardsFilter, setCardsFilter] = useState('mix');
  const [selectedCardThemes, setSelectedCardThemes] = useState([]);
  const [selectedCardTypes, setSelectedCardTypes] = useState([]);
  const [selectedCardLevels, setSelectedCardLevels] = useState([]);
  const [selectedCardSections, setSelectedCardSections] = useState([]);
  const [dialogsMenuMode, setDialogsMenuMode] = useState(false);
  const [dialogsMode, setDialogsMode] = useState(false);
  const [storyMode, setStoryMode] = useState(false);
  const [statsMode, setStatsMode] = useState(false);
  const [grammarMode, setGrammarMode] = useState(false);
  const [playsMode, setPlaysMode] = useState(false);
  const [activePlayGame, setActivePlayGame] = useState(null);
  const [dialogsSettings, setDialogsSettings] = useState(null);
  const isLanguageSelectionScreen = isLoggedIn && !showMainMenu;
  const isAuthOrLanguageSelectionScreen = !isLoggedIn || isLanguageSelectionScreen;
  const appThemeLanguage = languages?.learning?.[0] || languages?.native || 'EN';
  const appThemeVars = getLanguageCssVars(appThemeLanguage);
  const appStyle = isAuthOrLanguageSelectionScreen
    ? { ...appThemeVars, '--bg-start': '#FFFFFF', '--bg-end': '#FFFFFF' }
    : appThemeVars;

  const connections = LanguagesConnections?.LanguagesConnections || [];
  const sectionById = new Map((WordsSection?.WordsSection || []).map(item => [Number(item.WS_id), item.section]));
  const languageIdFieldByLang = {
    EN: 'EN_id',
    DE: 'DE_id',
    ES: 'ES_id',
    RU: 'RU_id'
  };
  const normalizeSection = (value) => {
    const parsed = Number(value);
    if (Number.isNaN(parsed)) return 1;
    return Math.max(1, Math.min(5, Math.trunc(parsed)));
  };

  const normalizeLanguages = (value) => {
    const native = value?.native ?? null;
    const learningRaw = value?.learning ?? [];
    const learning = Array.isArray(learningRaw)
      ? learningRaw
      : (learningRaw ? [learningRaw] : []);
    return { native, learning };
  };

  const loadUserSettings = async (user) => {
    if (!user) return;
    const localKey = `languages__${user}`;

    try {
      const data = await getUserSettingsSvc();
      const normalized = normalizeLanguages(data);
      setLanguages(normalized);
      const hasLanguages = !!normalized.native && normalized.learning.length > 0;
      setShowMainMenu(hasLanguages);
      localStorage.setItem(localKey, JSON.stringify(normalized));
    } catch (error) {
      console.error('Ошибка при загрузке настроек:', error);
      const cached = localStorage.getItem(localKey);
      if (cached) {
        const normalized = normalizeLanguages(JSON.parse(cached));
        setLanguages(normalized);
        const hasLanguages = !!normalized.native && normalized.learning.length > 0;
        setShowMainMenu(hasLanguages);
      }
    }
  };

  const saveUserSettings = async (user, data) => {
    if (!user) return;
    const normalized = normalizeLanguages(data);
    const localKey = `languages__${user}`;
    localStorage.setItem(localKey, JSON.stringify(normalized));

    try {
      await saveUserSettingsSvc(normalized);
    } catch (error) {
      console.error('Ошибка при сохранении настроек:', error);
    }
  };

  const syncUserTableWithLibrary = async (user, learningLang) => {
    if (!user) return;
    if (!learningLang) return;

    const learningIdField = languageIdFieldByLang[learningLang] || 'ES_id';
    const sectionByLearningId = new Map();
    connections.forEach(conn => {
      const learningId = Number(conn[learningIdField]);
      if (Number.isNaN(learningId) || sectionByLearningId.has(learningId)) return;
      sectionByLearningId.set(learningId, Number(sectionById.get(Number(conn.WS_id))) || 1);
    });

    let localTable = [];

    try {
      const serverData = await getUserTableSvc(learningLang);
      localTable = Array.isArray(serverData) ? serverData : [];
    } catch (error) {
      console.error('Ошибка загрузки данных с сервера:', error);
    }

    const libraryTable = await loadLanguageTable(learningLang);
    const progressByWordId = new Map();
    localTable.forEach(item => {
      const wordId = Number(item?.wordId);
      if (Number.isNaN(wordId) || wordId <= 0) return;
      progressByWordId.set(wordId, normalizeSection(item?.section));
    });

    const normalizedProgress = (libraryTable || []).map(item => {
      const wordId = Number(item[learningIdField]);
      if (Number.isNaN(wordId) || wordId <= 0) return null;
      return {
        wordId,
        section: progressByWordId.has(wordId)
          ? progressByWordId.get(wordId)
          : normalizeSection(Number(item.section) || Number(sectionByLearningId.get(wordId)) || 1)
      };
    }).filter(Boolean);

    const shouldSave =
      normalizedProgress.length !== localTable.length ||
      localTable.some(item => item?.wordId === undefined || Object.keys(item || {}).some(key => key !== 'wordId' && key !== 'section'));

    if (shouldSave) {
      try {
        await saveUserTableSvc(learningLang, normalizedProgress);
      } catch (error) {
        console.error('Ошибка сохранения на сервер:', error);
      }
    }
  };

  useEffect(() => {
    if (isLoggedIn && currentUser && languages?.learning?.[0]) {
      syncUserTableWithLibrary(currentUser, languages.learning[0]);
    }
  }, [isLoggedIn, currentUser, languages?.learning?.[0]]);

  useEffect(() => {
    if (isLoggedIn && currentUser) {
      loadUserSettings(currentUser);
    }
  }, [isLoggedIn, currentUser]);


  // Восстанавливаем сессию Supabase при загрузке страницы
  useEffect(() => {
    const restoreSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.user) return;

      const username = session.user.user_metadata?.username;
      if (!username) return;

      const savedMainMenu = localStorage.getItem('showMainMenu') === 'true';
      const savedCardsMenuMode = localStorage.getItem('cardsMenuMode') === 'true';
      const savedCardsMode = localStorage.getItem('cardsMode') === 'true';
      const savedCardsFilter = localStorage.getItem('cardsFilter');
      const savedDialogsMenuMode = localStorage.getItem('dialogsMenuMode') === 'true';
      const savedSelectedCardThemes = localStorage.getItem('selectedCardThemes');
      const savedSelectedCardTypes = localStorage.getItem('selectedCardTypes');
      const savedSelectedCardLevels = localStorage.getItem('selectedCardLevels');
      const savedSelectedCardSections = localStorage.getItem('selectedCardSections');
      const legacySelectedCardLevel = localStorage.getItem('selectedCardLevel');
      const legacySelectedCardSection = localStorage.getItem('selectedCardSection');

      setCurrentUser(username);
      localStorage.setItem('currentUser', username);
      setIsLoggedIn(true);
      setShowMainMenu(savedMainMenu);
      setCardsMenuMode(savedCardsMenuMode);
      setCardsMode(savedCardsMode);
      setDialogsMenuMode(savedDialogsMenuMode);

      if (savedCardsFilter) setCardsFilter(savedCardsFilter);
      if (savedSelectedCardThemes) setSelectedCardThemes(JSON.parse(savedSelectedCardThemes));
      if (savedSelectedCardTypes) setSelectedCardTypes(JSON.parse(savedSelectedCardTypes));
      if (savedSelectedCardLevels) {
        setSelectedCardLevels(JSON.parse(savedSelectedCardLevels));
      } else if (legacySelectedCardLevel && legacySelectedCardLevel !== 'all') {
        setSelectedCardLevels([legacySelectedCardLevel]);
      }
      if (savedSelectedCardSections) {
        setSelectedCardSections(JSON.parse(savedSelectedCardSections));
      } else if (legacySelectedCardSection && legacySelectedCardSection !== 'all') {
        setSelectedCardSections([legacySelectedCardSection]);
      }

      const cachedLanguages = localStorage.getItem(`languages__${username}`);
      if (cachedLanguages) {
        setLanguages(normalizeLanguages(JSON.parse(cachedLanguages)));
      }
    };

    restoreSession();
  }, []);

  // Сохраняем состояние showMainMenu
  useEffect(() => {
    localStorage.setItem('showMainMenu', showMainMenu);
  }, [showMainMenu]);

  // Сохраняем состояние cardsMenuMode
  useEffect(() => {
    localStorage.setItem('cardsMenuMode', cardsMenuMode);
  }, [cardsMenuMode]);

  // Сохраняем состояние cardsMode
  useEffect(() => {
    localStorage.setItem('cardsMode', cardsMode);
  }, [cardsMode]);

  // Сохраняем состояние dialogsMenuMode
  useEffect(() => {
    localStorage.setItem('dialogsMenuMode', dialogsMenuMode);
  }, [dialogsMenuMode]);

  // Сохраняем режим карточек
  useEffect(() => {
    localStorage.setItem('cardsFilter', cardsFilter);
  }, [cardsFilter]);

  // Сохраняем выбранные темы карточек
  useEffect(() => {
    localStorage.setItem('selectedCardThemes', JSON.stringify(selectedCardThemes));
  }, [selectedCardThemes]);

  useEffect(() => {
    localStorage.setItem('selectedCardTypes', JSON.stringify(selectedCardTypes));
  }, [selectedCardTypes]);

  useEffect(() => {
    localStorage.setItem('selectedCardLevels', JSON.stringify(selectedCardLevels));
  }, [selectedCardLevels]);

  useEffect(() => {
    localStorage.setItem('selectedCardSections', JSON.stringify(selectedCardSections));
  }, [selectedCardSections]);

  // Сохраняем выбранные языки
  useEffect(() => {
    if (!currentUser) return;
    if (!languages?.native && (!languages?.learning || languages.learning.length === 0)) return;
    saveUserSettings(currentUser, languages);
  }, [currentUser, languages]);

  // Функция для выхода из аккаунта
  const handleLogout = () => {
    logoutSvc(); // Supabase signOut (async, не ждём)
    // Очищаем localStorage
    localStorage.removeItem('currentUser');
    localStorage.removeItem('showMainMenu');
    localStorage.removeItem('cardsMenuMode');
    localStorage.removeItem('cardsMode');
    localStorage.removeItem('cardsFilter');
    localStorage.removeItem('dialogsMenuMode');
    localStorage.removeItem('selectedCardThemes');
    localStorage.removeItem('selectedCardTypes');
    localStorage.removeItem('selectedCardLevels');
    localStorage.removeItem('selectedCardSections');
    localStorage.removeItem('selectedCardLevel');
    localStorage.removeItem('selectedCardSection');
    if (currentUser) {
      localStorage.removeItem(`languages__${currentUser}`);
    }
    
    // Сбрасываем состояния
    setIsLoggedIn(false);
    setCurrentUser(null);
    setShowMainMenu(false);
    setCardsMenuMode(false);
    setCardsMode(false);
    setCardsFilter('mix');
    setSelectedCardThemes([]);
    setSelectedCardTypes([]);
    setSelectedCardLevels([]);
    setSelectedCardSections([]);
    setDialogsMenuMode(false);
    setStoryMode(false);
    setStatsMode(false);
    setGrammarMode(false);
    setPlaysMode(false);
    setActivePlayGame(null);
    setLanguages({
      native: null,
      learning: [],
    });
  };

  const handleDeleteAccount = async () => {
    if (!currentUser) return;
    try {
      await deleteAccountSvc();
      handleLogout();
    } catch (error) {
      console.error('Ошибка при удалении аккаунта:', error);
    }
  };

  const handleAddLearningLanguage = (languageId) => {
    setLanguages(prev => {
      const learning = Array.isArray(prev.learning)
        ? prev.learning
        : (prev.learning ? [prev.learning] : []);
      if (learning.includes(languageId)) return prev;
      return { ...prev, learning: [...learning, languageId] };
    });
  };

  const handleSetActiveLearning = (languageId) => {
    setLanguages(prev => {
      const learning = Array.isArray(prev.learning)
        ? prev.learning
        : (prev.learning ? [prev.learning] : []);
      if (!learning.includes(languageId)) return prev;
      const next = [languageId, ...learning.filter(id => id !== languageId)];
      return { ...prev, learning: next };
    });
  };

  return (
    <div className="App" style={appStyle}>
      <main className="main-content">
        {!isLoggedIn && (
          <Login
            setIsLoggedIn={setIsLoggedIn}
            setCurrentUser={setCurrentUser}
            uiLang={languages?.native}
            activeLearningLang={languages?.learning?.[0]}
          />
        )}
        {isLoggedIn && !showMainMenu && <StartChoosingLanguages setLanguages={setLanguages} setShowMainMenu={setShowMainMenu} uiLang={languages?.native} />}
        {isLoggedIn && showMainMenu && !cardsMenuMode && !cardsMode && !dialogsMenuMode && !dialogsMode && !storyMode && !statsMode && !grammarMode && !playsMode && (
          <MainMenu
            languages={languages}
            setCardsMenuMode={setCardsMenuMode}
            setDialogsMenuMode={setDialogsMenuMode}
            setStoryMode={setStoryMode}
            setStatsMode={setStatsMode}
            setGrammarMode={setGrammarMode}
            setPlaysMode={setPlaysMode}
            onLogout={handleLogout}
            onDeleteAccount={handleDeleteAccount}
            onAddLearningLanguage={handleAddLearningLanguage}
            onSetActiveLearning={handleSetActiveLearning}
          />
        )}
        {isLoggedIn && grammarMode && (
          <Grammar
            onBack={() => setGrammarMode(false)}
            uiLang={languages?.native}
            learningLang={languages?.learning?.[0]}
          />
        )}
        {isLoggedIn && playsMode && !activePlayGame && (
          <PlaysMenu
            onBack={() => {
              setActivePlayGame(null);
              setPlaysMode(false);
            }}
            uiLang={languages?.native}
            onStartGame={(gameId) => {
              setActivePlayGame(gameId);
            }}
          />
        )}
        {isLoggedIn && playsMode && activePlayGame === 'first-letter' && (
          <TheFirstLetterMenu
            onBack={() => setActivePlayGame(null)}
            uiLang={languages?.native}
            learningLang={languages?.learning?.[0]}
            currentUser={currentUser}
          />
        )}
        {isLoggedIn && statsMode && (
          <Stats
            onBack={() => setStatsMode(false)}
            uiLang={languages?.native}
            languages={languages}
            learningLang={languages?.learning?.[0]}
          />
        )}
        {isLoggedIn && storyMode && (
          <Story
            onBack={() => setStoryMode(false)}
            uiLang={languages?.native}
            learningLang={languages?.learning?.[0]}
          />
        )}
        {isLoggedIn && cardsMenuMode && (
          <CardsMenu
            onBack={() => setCardsMenuMode(false)}
            uiLang={languages?.native}
            learningLang={languages?.learning?.[0]}
            onSelectMode={(mode, themes, types, levels, sections) => {
              setCardsFilter(mode);
              setSelectedCardThemes(themes);
              setSelectedCardTypes(types || []);
              setSelectedCardLevels(levels || []);
              setSelectedCardSections(sections || []);
              setCardsMenuMode(false);
              setCardsMode(true);
            }}
          />
        )}
        {isLoggedIn && cardsMode && (
          <Cards
            setCardsMode={setCardsMode}
            setCardsMenuMode={setCardsMenuMode}
            cardsFilter={cardsFilter}
            selectedCardThemes={selectedCardThemes}
            selectedCardTypes={selectedCardTypes}
            selectedCardLevels={selectedCardLevels}
            selectedCardSections={selectedCardSections}
            uiLang={languages?.native}
            nativeLang={languages?.native}
            learningLang={languages?.learning?.[0]}
          />
        )}
        {isLoggedIn && dialogsMenuMode && (
          <DialogsMenu
            onBack={() => setDialogsMenuMode(false)}
            uiLang={languages?.native}
            learningLang={languages?.learning?.[0]}
            onStart={(settings) => {
              setDialogsSettings(settings);
              setDialogsMenuMode(false);
              setDialogsMode(true);
            }}
          />
        )}
        {isLoggedIn && dialogsMode && (
          <Dialogs
            onBack={() => {
              setDialogsMode(false);
              setDialogsMenuMode(true);
            }}
            uiLang={languages?.native}
            settings={dialogsSettings}
          />
        )}
      </main>
    </div>
  );
}

export default App;