import React, { useEffect, useState } from 'react';
import { t } from '../../i18n';
import { getLanguageCssVars } from '../ColorsMap';
import './grammar.css';

const Grammar = ({ onBack, uiLang, learningLang }) => {
	const [grammarContent, setGrammarContent] = useState('');
	const activeLearningLang = learningLang || uiLang || 'EN';
	const themeVars = getLanguageCssVars(learningLang || uiLang || 'EN');

	useEffect(() => {
		let isMounted = true;

		const loadGrammarScript = async () => {
			try {
				const grammarModule = await import(
					`../../grammarLibrary/grammar_${activeLearningLang}/grammar_${activeLearningLang}.js`
				);
				if (isMounted) {
					setGrammarContent(grammarModule.default || '');
				}
			} catch (error) {
				console.error('Grammar load error:', error);
				if (isMounted) {
					setGrammarContent('');
				}
			}
		};

		loadGrammarScript();

		return () => {
			isMounted = false;
		};
	}, [activeLearningLang]);

	const isComponent = typeof grammarContent === 'function';

	return (
		<div className="grammar-container" style={themeVars}>
			<button className="grammar-back-button" onClick={onBack}>
				{t('back', uiLang)}
			</button>
			<div className="grammar-content">
				{isComponent
					? React.createElement(grammarContent, { uiLang, learningLang })
					: grammarContent || t('menuGrammar', uiLang)}
			</div>
		</div>
	);
};

export default Grammar;
