import React from 'react';
import { t } from '../../../i18n';
import './FiveSectionsInfo.css';

const FiveSectionsInfo = ({ isOpen, onClose, uiLang }) => {
  if (!isOpen) return null;

  return (
    <div className="five-sections-overlay" onClick={onClose}>
      <div className="five-sections-modal" onClick={(e) => e.stopPropagation()}>
        <button className="five-sections-close" onClick={onClose} aria-label={t('fiveSectionsCloseAria', uiLang)}>
          x
        </button>

        <h2 className="five-sections-title">{t('fiveSectionsTitle', uiLang)}</h2>
        <p className="five-sections-intro">
          {t('fiveSectionsIntro', uiLang)}
        </p>

        <div className="five-sections-grid">
          <div className="five-sections-card">
            <h3>{t('fiveSectionsSection1Title', uiLang)}</h3>
            <p>{t('fiveSectionsSection1Text', uiLang)}</p>
          </div>
          <div className="five-sections-card">
            <h3>{t('fiveSectionsSection2Title', uiLang)}</h3>
            <p>{t('fiveSectionsSection2Text', uiLang)}</p>
          </div>
          <div className="five-sections-card">
            <h3>{t('fiveSectionsSection3Title', uiLang)}</h3>
            <p>{t('fiveSectionsSection3Text', uiLang)}</p>
          </div>
          <div className="five-sections-card">
            <h3>{t('fiveSectionsSection4Title', uiLang)}</h3>
            <p>{t('fiveSectionsSection4Text', uiLang)}</p>
          </div>
          <div className="five-sections-card">
            <h3>{t('fiveSectionsSection5Title', uiLang)}</h3>
            <p>{t('fiveSectionsSection5Text', uiLang)}</p>
          </div>
        </div>

        <p className="five-sections-note">
          {t('fiveSectionsNote', uiLang)}
        </p>

        <div className="five-sections-recommendations">
          <h3 className="five-sections-recommendations-title">{t('fiveSectionsRecommendationsTitle', uiLang)}</h3>
          <ul className="five-sections-recommendations-list">
            <li>{t('fiveSectionsRecommendation1', uiLang)}</li>
            <li>{t('fiveSectionsRecommendation2', uiLang)}</li>
            <li>{t('fiveSectionsRecommendation3', uiLang)}</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default FiveSectionsInfo;
