import React, { useState } from 'react';
import { t } from '../../i18n';
import { getLanguageCssVars } from '../ColorsMap';
import { login as doLogin, register as doRegister } from '../../lib/userService';
import './Login.css';

const Login = ({ setIsLoggedIn, setCurrentUser, uiLang, activeLearningLang }) => {
  const [login, setLogin] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isRegister, setIsRegister] = useState(false);
  const themeVars = getLanguageCssVars(activeLearningLang || uiLang);

  const getPasswordTooShortText = () => t('registerPasswordTooShort', uiLang);

  const finishAuthSuccess = (username) => {
    setCurrentUser(username);
    localStorage.setItem('currentUser', username);
    setIsLoggedIn(true);
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      if (!login || !password) {
        setError(t('authFillAll', uiLang));
        return;
      }
      if (isRegister && String(password).length < 6) {
        setError(getPasswordTooShortText());
        return;
      }

      try {
        let username;
        if (isRegister) {
          username = await doRegister(login.trim(), password);
        } else {
          username = await doLogin(login.trim(), password);
        }
        finishAuthSuccess(username);
      } catch (err) {
        console.error('[auth] error:', err?.message, err);
        const msg = String(err?.message || '').toLowerCase();
        if (isRegister) {
          if (msg.includes('already registered') || msg.includes('already exists') || msg.includes('user_already_exists')) {
            setError(t('registerExists', uiLang));
          } else if (msg.includes('invalid_input') || msg.includes('weak password') || msg.includes('weak_password') || msg.includes('at least 6 characters')) {
            setError(t('registerInvalid', uiLang));
          } else if (msg.includes('email_confirmation_required') || msg.includes('email not confirmed')) {
            setError(t('registerEmailConfirm', uiLang));
          } else if (msg.includes('email address') || msg.includes('invalid email')) {
            setError(t('registerServerError', uiLang));
          } else {
            setError(t('registerFailed', uiLang));
          }
        } else {
          if (msg.includes('invalid login credentials') || msg.includes('invalid_credentials')) {
            setError(t('loginError', uiLang));
          } else {
            setError(t('loginError', uiLang));
          }
        }
        setPassword('');
      }
    } catch (err) {
      console.error('Ошибка при авторизации:', err);
      setError(isRegister ? t('registerFailed', uiLang) : t('loginError', uiLang));
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="login-container" style={themeVars}>
      <div className="login-box">
        <h1 className="login-title">LaLU</h1>
        <form onSubmit={handleLogin} className="login-form">
          <div className="form-group">
            <label htmlFor="login" className="form-label">{t('loginLabel', uiLang)}</label>
            <input
              id="login"
              type="text"
              className="form-input"
              value={login}
              onChange={(e) => setLogin(e.target.value)}
              placeholder={t('loginPlaceholder', uiLang)}
              disabled={isLoading}
              autoFocus
            />
          </div>

          <div className="form-group">
            <label htmlFor="password" className="form-label">{t('passwordLabel', uiLang)}</label>
            <input
              id="password"
              type="password"
              className="form-input"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder={t('passwordPlaceholder', uiLang)}
              disabled={isLoading}
              minLength={isRegister ? 6 : undefined}
              autoComplete={isRegister ? 'new-password' : 'current-password'}
            />
            {isRegister && (
              <div className="password-hint">{getPasswordTooShortText()}</div>
            )}
          </div>

          {error && <div className="error-message">{error}</div>}

          <button type="submit" className="login-button" disabled={isLoading}>
            {isLoading
              ? t('loginLoading', uiLang)
              : (isRegister ? t('registerSubmit', uiLang) : t('loginSubmit', uiLang))}
          </button>
        </form>

        <button
          type="button"
          className={`login-button ${isRegister ? 'login-button-secondary' : ''}`}
          disabled={isLoading}
          onClick={() => {
            setIsRegister(prev => !prev);
            setError('');
          }}
        >
          {isRegister ? t('switchToLogin', uiLang) : t('switchToRegister', uiLang)}
        </button>
      </div>
    </div>
  );
};

export default Login;
