/**
 * userService.js — вся логика работы с пользователем напрямую через Supabase.
 * Заменяет Express-backend (server.js) без изменения поведения приложения.
 */

import { supabase } from './supabase';
import { loadLanguageTable } from '../utils/availableLanguages';

// ─── Helpers ──────────────────────────────────────────────────────────────────

const normalizeLanguageId = (id) => String(id || '').trim().toUpperCase();
const isValidLanguageId = (id) => /^[A-Z]{2,5}$/.test(id || '');
const isValidUsername = (name) => /^[A-Za-z0-9_-]+$/.test(name || '');
const getTableName = (languageId) => `UserTable_${languageId}`;

const idFieldByLang = { EN: 'EN_id', DE: 'DE_id', ES: 'ES_id', RU: 'RU_id' };
const getIdField = (languageId) => idFieldByLang[languageId] || `${languageId}_id`;

const normalizeSection = (value) => {
  const n = Number(value);
  return Number.isNaN(n) ? 1 : Math.max(1, Math.min(5, Math.trunc(n)));
};

const extractWordId = (item, languageId) => {
  if (!item || typeof item !== 'object') return null;

  const directWordId = Number(item.wordId);
  if (!Number.isNaN(directWordId) && directWordId > 0) {
    return Math.trunc(directWordId);
  }

  const idField = getIdField(languageId);
  const legacyWordId = Number(item[idField]);
  if (!Number.isNaN(legacyWordId) && legacyWordId > 0) {
    return Math.trunc(legacyWordId);
  }

  return null;
};

/** Возвращает email-идентификатор для Supabase Auth из имени пользователя. */
const toAuthEmail = (username) => `${username.toLowerCase().trim()}@languageup.app`;
const toLegacyAuthEmail = (username) => `${username.toLowerCase().trim()}@languageup.internal`;

const buildPasswordHash = async (password) => {
  if (!window?.crypto?.subtle) {
    throw new Error('crypto_unavailable');
  }

  const salt = window.crypto.getRandomValues(new Uint8Array(16));
  const saltHex = Array.from(salt).map((b) => b.toString(16).padStart(2, '0')).join('');
  const encoded = new TextEncoder().encode(saltHex + password);
  const hashBuf = await window.crypto.subtle.digest('SHA-256', encoded);
  const hashHex = Array.from(new Uint8Array(hashBuf)).map((b) => b.toString(16).padStart(2, '0')).join('');
  return `sha256:${saltHex}:${hashHex}`;
};

// ─── Auth ─────────────────────────────────────────────────────────────────────

/**
 * Логин. Возвращает отображаемое имя пользователя.
 * @throws {Error} при неверных данных
 */
export const login = async (username, password) => {
  if (!isValidUsername(username) || !password) {
    throw new Error('invalid_input');
  }
  const candidates = [toAuthEmail(username), toLegacyAuthEmail(username)];
  let lastError = null;

  for (const email of candidates) {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (!error) {
      return data.user?.user_metadata?.username || username;
    }
    const msg = String(error?.message || '').toLowerCase();
    // Для не-credential ошибок сразу прерываемся, чтобы не маскировать реальную проблему
    if (!msg.includes('invalid login credentials')) {
      throw error;
    }
    lastError = error;
  }

  if (lastError) throw lastError;
  throw new Error('invalid_credentials');
};

/**
 * Регистрация. Возвращает отображаемое имя пользователя.
 * Требует отключённого email-подтверждения в Supabase (Authentication → Settings).
 * @throws {Error} при конфликте или невалидных данных
 */
export const register = async (username, password) => {
  const trimmed = username.trim();
  if (!isValidUsername(trimmed) || !password) {
    throw new Error('invalid_input');
  }
  if (String(password).length < 6) {
    throw new Error('weak_password');
  }
  const email = toAuthEmail(trimmed);

  const { data, error } = await supabase.auth.signUp({
    email,
    password,
    options: { data: { username: trimmed } }
  });

  if (error) {
    console.error('[register] signUp error:', error.message, error);
    throw error;
  }
  if (!data.user) throw new Error('registration_failed');
  if (!data.session) {
    console.warn('[register] signUp returned no session — email confirmation may be ON in Supabase Dashboard');
    throw new Error('email_confirmation_required');
  }

  // Эта запись только для видимости в Supabase Table Editor — не влияет на функционал
  try {
    const passwordHash = await buildPasswordHash(password);
    const { error: usersErr } = await supabase
      .from('users')
      .insert({ user_id: data.user.id, username: trimmed, password_hash: passwordHash });
    if (usersErr && usersErr.code !== '23505') {
      console.warn('[register] public.users insert skipped:', usersErr.message);
    }
  } catch (e) {
    console.warn('[register] public.users insert failed (non-fatal):', e.message);
  }

  // Создаём строку настроек при первой регистрации
  const { error: settingsErr } = await supabase
    .from('user_settings')
    .insert({ user_id: data.user.id, native: null, learning: [] });

  // Игнорируем «уже существует» (дубль вставки)
  if (settingsErr && settingsErr.code !== '23505') {
    console.error('[register] user_settings insert error:', settingsErr.message, settingsErr);
    throw settingsErr;
  }

  return data.user.user_metadata?.username || trimmed;
};

/** Выход из системы. */
export const logout = async () => {
  await supabase.auth.signOut();
};

/**
 * Удаление аккаунта через хранимую функцию delete_current_user().
 * Данные в user_settings и user_language_tables удаляются каскадно.
 */
export const deleteAccount = async () => {
  const { error } = await supabase.rpc('delete_current_user');
  if (error) throw error;
};

/**
 * Смена пароля текущего пользователя.
 * Проверяет старый пароль, обновляет новый в Supabase Auth
 * и сохраняет новый hash в public.users.password_hash.
 */
export const resetPassword = async (oldPassword, newPassword) => {
  if (!oldPassword || !newPassword) {
    throw new Error('invalid_input');
  }
  if (String(newPassword).length < 6) {
    throw new Error('weak_password');
  }

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  const username = user.user_metadata?.username;
  if (!isValidUsername(username)) {
    throw new Error('invalid_user');
  }

  const emails = [toAuthEmail(username), toLegacyAuthEmail(username)];
  let verified = false;
  let lastError = null;

  for (const email of emails) {
    const { error } = await supabase.auth.signInWithPassword({ email, password: oldPassword });
    if (!error) {
      verified = true;
      break;
    }
    const msg = String(error?.message || '').toLowerCase();
    if (!msg.includes('invalid login credentials')) {
      throw error;
    }
    lastError = error;
  }

  if (!verified) {
    if (lastError) throw new Error('invalid_current_password');
    throw new Error('invalid_current_password');
  }

  const { error: updateAuthError } = await supabase.auth.updateUser({ password: newPassword });
  if (updateAuthError) throw updateAuthError;

  try {
    const passwordHash = await buildPasswordHash(newPassword);
    const { error: usersErr } = await supabase
      .from('users')
      .update({ password_hash: passwordHash })
      .eq('user_id', user.id);
    if (usersErr) {
      console.warn('[resetPassword] users hash update failed:', usersErr.message);
    }
  } catch (error) {
    console.warn('[resetPassword] hash generation failed:', error?.message || error);
  }
};

/** Возвращает текущую Supabase-сессию или null. */
export const getSession = async () => {
  const { data: { session } } = await supabase.auth.getSession();
  return session;
};

/** Возвращает отображаемое имя текущего пользователя или null. */
export const getCurrentUsername = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  return user?.user_metadata?.username || null;
};

// ─── Settings ─────────────────────────────────────────────────────────────────

/** Загружает настройки текущего пользователя. */
export const getUserSettings = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  const { data, error } = await supabase
    .from('user_settings')
    .select('native, learning')
    .eq('user_id', user.id)
    .maybeSingle();

  if (error) throw error;

  if (!data) {
    await supabase.from('user_settings').insert({ user_id: user.id, native: null, learning: [] });
    return { native: null, learning: [] };
  }

  return {
    native: data.native || null,
    learning: Array.isArray(data.learning) ? data.learning : []
  };
};

/** Сохраняет настройки текущего пользователя. */
export const saveUserSettings = async (settings) => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  const native = settings?.native ? normalizeLanguageId(settings.native) : null;
  const learningRaw = Array.isArray(settings?.learning) ? settings.learning : [];
  const learning = [...new Set(learningRaw.map(normalizeLanguageId).filter(isValidLanguageId))];

  const { error } = await supabase
    .from('user_settings')
    .upsert(
      { user_id: user.id, native, learning, updated_at: new Date().toISOString() },
      { onConflict: 'user_id' }
    );

  if (error) throw error;

  // Убеждаемся, что строки для изучаемых языков существуют
  for (const languageId of learning) {
    await ensureLanguageTableRow(user.id, languageId);
  }
};

// ─── User language table ───────────────────────────────────────────────────────

/** Создаёт строку таблицы прогресса по языку, если её ещё нет. */
const ensureLanguageTableRow = async (userId, languageId) => {
  const tableName = getTableName(languageId);

  const { data: existing } = await supabase
    .from('user_language_tables')
    .select('user_id')
    .eq('user_id', userId)
    .eq('table_name', tableName)
    .maybeSingle();

  if (existing) return;

  const defaultData = await buildDefaultTableData(languageId);

  const { error } = await supabase.from('user_language_tables').insert({
    user_id: userId,
    language_id: languageId,
    table_name: tableName,
    table_data: defaultData
  });

  // Игнорируем race-condition дубль
  if (error && error.code !== '23505') throw error;
};

/** Строит начальную таблицу прогресса из словарного JSON.
 * Формат хранения: { ES_id: x, section: 1 } */
const buildDefaultTableData = async (languageId) => {
  const idField = getIdField(languageId);
  const wordTable = await loadLanguageTable(languageId);

  const rows = wordTable
    .map((item) => {
      const wordId = Number(item?.[idField]);
      if (Number.isNaN(wordId) || wordId <= 0) return null;
      return { [idField]: Math.trunc(wordId), section: 1 };
    })
    .filter(Boolean);

  const byId = new Map();
  rows.forEach((item) => {
    byId.set(Number(item[idField]), item);
  });

  return [...byId.values()].sort((a, b) => a[idField] - b[idField]);
};

const normalizeTableData = async (tableData, languageId) => {
  const idField = getIdField(languageId);
  const defaultRows = await buildDefaultTableData(languageId);

  if (!idField) {
    return [];
  }

  const byId = new Map(defaultRows.map((item) => [Number(item[idField]), item]));
  (Array.isArray(tableData) ? tableData : []).forEach((item) => {
    const wordId = extractWordId(item, languageId);
    if (!wordId || !byId.has(wordId)) return;

    byId.set(wordId, {
      [idField]: wordId,
      section: normalizeSection(item?.section ?? item?.Section)
    });
  });

  return [...byId.values()].sort((a, b) => a[idField] - b[idField]);
};

const mergeTableDataPreservingExisting = async (existingTableData, incomingTableData, languageId) => {
  const existingNormalized = await normalizeTableData(existingTableData, languageId);
  // Incoming items should override existing values only for provided words.
  return normalizeTableData([...(existingNormalized || []), ...(Array.isArray(incomingTableData) ? incomingTableData : [])], languageId);
};

/**
 * Возвращает таблицу прогресса пользователя по языку.
 * Формат: [{wordId: number, section: number}, ...]
 */
export const getUserTable = async (languageId) => {
  const langId = normalizeLanguageId(languageId);
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  await ensureLanguageTableRow(user.id, langId);

  const tableName = getTableName(langId);
  const idField = getIdField(langId);

  const { data, error } = await supabase
    .from('user_language_tables')
    .select('table_data')
    .eq('user_id', user.id)
    .eq('table_name', tableName)
    .single();

  if (error) throw error;

  const list = await normalizeTableData(data?.table_data, langId);
  const rawList = Array.isArray(data?.table_data) ? data.table_data : [];

  if (JSON.stringify(rawList) !== JSON.stringify(list)) {
    const { error: updateError } = await supabase
      .from('user_language_tables')
      .update({ table_data: list, updated_at: new Date().toISOString() })
      .eq('user_id', user.id)
      .eq('table_name', tableName);

    if (updateError) throw updateError;
  }

  // Поддержка обоих форматов: старый {ES_id: x} и новый {wordId: x}
  return list
    .map((item) => {
      const wordId = Number(item?.wordId ?? item?.[idField]);
      if (Number.isNaN(wordId) || wordId <= 0) return null;
      return { wordId, section: normalizeSection(item?.section ?? item?.Section) };
    })
    .filter(Boolean)
    .sort((a, b) => a.wordId - b.wordId);
};

/**
 * Сохраняет таблицу прогресса пользователя по языку.
 * @param {string} languageId
 * @param {Array<{wordId: number, section: number}>} tableData
 */
export const saveUserTable = async (languageId, tableData) => {
  const langId = normalizeLanguageId(languageId);
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');
  if (!Array.isArray(tableData)) throw new Error('invalid_data');

  await ensureLanguageTableRow(user.id, langId);

  const tableName = getTableName(langId);
  const { data: existingRow, error: readError } = await supabase
    .from('user_language_tables')
    .select('table_data')
    .eq('user_id', user.id)
    .eq('table_name', tableName)
    .single();

  if (readError) throw readError;

  const normalized = await mergeTableDataPreservingExisting(existingRow?.table_data, tableData, langId);

  const { error } = await supabase
    .from('user_language_tables')
    .update({ table_data: normalized, updated_at: new Date().toISOString() })
    .eq('user_id', user.id)
    .eq('table_name', tableName);

  if (error) throw error;
};

// ─── Grammar progress (A1) ───────────────────────────────────────────────────

const normalizeGrammarProgressId = (value) => {
  const id = String(value || '').trim();
  return /^\d+$/.test(id) ? id : null;
};

const normalizeGrammarResult = (value) => (String(value) === '1' ? '1' : '0');

const normalizeGrammarProgressList = (list) => {
  const map = new Map();

  (Array.isArray(list) ? list : []).forEach((item) => {
    const id = normalizeGrammarProgressId(item?.id);
    if (!id) return;
    map.set(id, { id, result: normalizeGrammarResult(item?.result) });
  });

  return [...map.values()].sort((a, b) => Number(a.id) - Number(b.id));
};

const buildDefaultGrammarProgress = (sectionIds) => {
  const uniqueIds = [...new Set((Array.isArray(sectionIds) ? sectionIds : [])
    .map((id) => normalizeGrammarProgressId(id))
    .filter(Boolean))]
    .sort((a, b) => Number(a) - Number(b));

  return uniqueIds.map((id) => ({ id, result: '0' }));
};

/**
 * Загружает прогресс раздела Grammar A1 по языку.
 * Формат: [{ id: "1", result: "0|1" }, ...]
 */
export const getGrammarProgress = async (languageId, sectionIds = []) => {
  const langId = normalizeLanguageId(languageId);
  if (!isValidLanguageId(langId)) throw new Error('invalid_language');

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  const defaultProgress = buildDefaultGrammarProgress(sectionIds);

  const { data, error } = await supabase
    .from('grammar_progress')
    .select('grammar_a1_data')
    .eq('user_id', user.id)
    .eq('language_id', langId)
    .maybeSingle();

  if (error) throw error;

  if (!data) {
    const { error: insertError } = await supabase
      .from('grammar_progress')
      .insert({ user_id: user.id, language_id: langId, grammar_a1_data: defaultProgress });

    if (insertError && insertError.code !== '23505') throw insertError;
    return defaultProgress;
  }

  const normalizedStored = normalizeGrammarProgressList(data?.grammar_a1_data);
  if (defaultProgress.length === 0) {
    return normalizedStored;
  }

  const merged = defaultProgress.map((item) => {
    const stored = normalizedStored.find((row) => row.id === item.id);
    return stored ? { id: item.id, result: stored.result } : item;
  });

  if (JSON.stringify(merged) !== JSON.stringify(normalizedStored)) {
    const { error: updateError } = await supabase
      .from('grammar_progress')
      .update({ grammar_a1_data: merged, updated_at: new Date().toISOString() })
      .eq('user_id', user.id)
      .eq('language_id', langId);

    if (updateError) throw updateError;
  }

  return merged;
};

/**
 * Сохраняет прогресс раздела Grammar A1 по языку.
 * @param {string} languageId
 * @param {Array<{id: string, result: string}>} grammarData
 */
export const saveGrammarProgress = async (languageId, grammarData) => {
  const langId = normalizeLanguageId(languageId);
  if (!isValidLanguageId(langId)) throw new Error('invalid_language');
  if (!Array.isArray(grammarData)) throw new Error('invalid_data');

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  const normalized = normalizeGrammarProgressList(grammarData);

  const { error } = await supabase
    .from('grammar_progress')
    .upsert(
      {
        user_id: user.id,
        language_id: langId,
        grammar_a1_data: normalized,
        updated_at: new Date().toISOString()
      },
      { onConflict: 'user_id,language_id' }
    );

  if (error) throw error;
};

// ─── The First Letter Game Results ────────────────────────────────────────────

/**
 * Возвращает результаты игры "The First Letter" текущего пользователя.
 * @returns {Promise<{last_result:number, best_result:number} | null>}
 * @throws {Error} при ошибке Supabase
 */
export const getFirstLetterResult = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  const { data, error } = await supabase
    .from('the_first_letter_results')
    .select('last_result, best_result')
    .eq('user_id', user.id)
    .maybeSingle();

  if (error) throw error;
  if (!data) return null;

  return {
    last_result: Number(data.last_result) || 0,
    best_result: Number(data.best_result) || 0,
  };
};

/**
 * Сохраняет результат игры "The First Letter" в таблицу the_first_letter_results.
 * Если запись пользователя существует, обновляет best_result (если новый результат больше) и last_result.
 * Если не существует, создаёт новую запись.
 * @param {number} score - Результат текущей сессии
 * @returns {Promise<{last_result:number, best_result:number}>}
 * @throws {Error} при ошибке Supabase
 */
export const saveFirstLetterResult = async (score) => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  const normalizedScore = Number(score) || 0;

  // Пытаемся получить существующую запись
  const { data: existing, error: selectError } = await supabase
    .from('the_first_letter_results')
    .select('best_result')
    .eq('user_id', user.id)
    .maybeSingle();

  if (selectError) throw selectError;

  const bestResult = existing ? Math.max(existing.best_result, normalizedScore) : normalizedScore;

  if (existing) {
    // Обновляем существующую запись
    const { data: updatedData, error: updateError } = await supabase
      .from('the_first_letter_results')
      .update({
        last_result: normalizedScore,
        best_result: bestResult,
        updated_at: new Date().toISOString()
      })
      .eq('user_id', user.id)
      .select('last_result, best_result')
      .single();

    if (updateError) throw updateError;
    return {
      last_result: Number(updatedData?.last_result) || normalizedScore,
      best_result: Number(updatedData?.best_result) || bestResult,
    };
  } else {
    // Создаём новую запись
    const { data: insertedData, error: insertError } = await supabase
      .from('the_first_letter_results')
      .insert({
        user_id: user.id,
        last_result: normalizedScore,
        best_result: bestResult
      })
      .select('last_result, best_result')
      .single();

    if (insertError) throw insertError;
    return {
      last_result: Number(insertedData?.last_result) || normalizedScore,
      best_result: Number(insertedData?.best_result) || bestResult,
    };
  }
};
