import React, { useState, useEffect } from 'react';
import LanguagesConnections from '../../../wordLibrary/LanguagesConnections.json';
import WordsCategory from '../../../wordLibrary/wordsParams/WordsCategory.json';
import WordsLvl from '../../../wordLibrary/wordsParams/WordsLvl.json';
import WordsPos from '../../../wordLibrary/wordsParams/WordsPos.json';
import { t, wordCountLabel, tCategory, tPos } from '../../../i18n';
import { getLanguageCssVars } from '../../ColorsMap';
import { getUserTable as fetchUserTable } from '../../../lib/userService';
import FiveSectionsInfo from './FiveSectionsInfo';
import './CardsMenu.css';

const CardsMenu = ({ onBack, onSelectMode, uiLang, learningLang }) => {
  const [hasRepeatWords, setHasRepeatWords] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isTypesDropdownOpen, setIsTypesDropdownOpen] = useState(false);
  const [isLevelsDropdownOpen, setIsLevelsDropdownOpen] = useState(false);
  const [isSectionsDropdownOpen, setIsSectionsDropdownOpen] = useState(false);
  const [isMethodologyOpen, setIsMethodologyOpen] = useState(false);
  const [progressSections, setProgressSections] = useState({});
  const [selectedThemes, setSelectedThemes] = useState(() => {
    // Загружаем сохраненные темы из localStorage
    const saved = localStorage.getItem('cardsMenuSelectedThemes');
    return saved ? new Set(JSON.parse(saved)) : new Set();
  });
  const [selectedTypes, setSelectedTypes] = useState(() => {
    const saved = localStorage.getItem('cardsMenuSelectedTypes');
    return saved ? new Set(JSON.parse(saved)) : new Set();
  });
  const [selectedLevels, setSelectedLevels] = useState(() => {
    const saved = localStorage.getItem('cardsMenuSelectedLevels');
    if (saved) return new Set(JSON.parse(saved));
    const legacy = localStorage.getItem('cardsMenuSelectedLevel');
    return legacy && legacy !== 'all' ? new Set([legacy]) : new Set();
  });
  const [selectedSections, setSelectedSections] = useState(() => {
    const saved = localStorage.getItem('cardsMenuSelectedSections');
    if (saved) return new Set(JSON.parse(saved));
    const legacy = localStorage.getItem('cardsMenuSelectedSection');
    return legacy && legacy !== 'all' ? new Set([legacy]) : new Set();
  });
  const resolvedLearningLang = learningLang || 'ES';
  const levelOptions = ['A1', 'A2', 'B1', 'B2', 'C1'];
  const sectionOptions = ['1', '2', '3', '4', '5'];
  const languageIdFieldByLang = {
    EN: 'EN_id',
    DE: 'DE_id',
    ES: 'ES_id',
    RU: 'RU_id'
  };
  const learningIdField = languageIdFieldByLang[resolvedLearningLang] || 'ES_id';
  const connections = LanguagesConnections?.LanguagesConnections || [];
  const categoryById = new Map((WordsCategory?.WordsCategory || []).map(item => [Number(item.CAT_id), item.category]));
  const levelById = new Map((WordsLvl?.WordsLvl || []).map(item => [Number(item.WL_id), item.lengLvl]));
  const posById = new Map((WordsPos?.WordsPos || []).map(item => [Number(item.WP_id), item.pos]));
  const uniqueLearningIds = new Set();
  const linkedItems = [];
  connections.forEach(conn => {
    const learningId = Number(conn[learningIdField]);
    if (Number.isNaN(learningId) || uniqueLearningIds.has(learningId)) return;
    uniqueLearningIds.add(learningId);
    linkedItems.push({
      learningId,
      category: categoryById.get(Number(conn.CAT_id)) || 'Other',
      pos: posById.get(Number(conn.WP_id)) || 'Other',
      level: levelById.get(Number(conn.WL_id)) || null,
      defaultSection: String(Number(conn.WS_id) || 1)
    });
  });

  const resolveItemSection = (item) => String(progressSections[item.learningId] || item.defaultSection || '1');

  const applyThemeFilter = (items, themes) => {
    if (!themes || themes.size === 0) return items;
    return items.filter(item => themes.has(item.category || 'Other'));
  };

  const applyTypeFilter = (items, types) => {
    if (!types || types.size === 0) return items;
    return items.filter(item => types.has(item.pos || 'Other'));
  };

  const applyLevelFilter = (items, level) => {
    if (!level || level.size === 0) return items;
    return items.filter(item => level.has(item.level));
  };

  const applySectionFilter = (items, section) => {
    if (!section || section.size === 0) return items;
    return items.filter(item => section.has(resolveItemSection(item)));
  };

  const buildCounts = (items, getKey) => {
    const counts = {};
    items.forEach(item => {
      const key = getKey(item);
      counts[key] = (counts[key] || 0) + 1;
    });
    return counts;
  };

  // Сохраняем выбранные темы в localStorage
  useEffect(() => {
    localStorage.setItem('cardsMenuSelectedThemes', JSON.stringify(Array.from(selectedThemes)));
  }, [selectedThemes]);

  useEffect(() => {
    localStorage.setItem('cardsMenuSelectedTypes', JSON.stringify(Array.from(selectedTypes)));
  }, [selectedTypes]);

  useEffect(() => {
    localStorage.setItem('cardsMenuSelectedLevels', JSON.stringify(Array.from(selectedLevels)));
  }, [selectedLevels]);

  useEffect(() => {
    localStorage.setItem('cardsMenuSelectedSections', JSON.stringify(Array.from(selectedSections)));
  }, [selectedSections]);

  useEffect(() => {
    const checkRepeatWords = async () => {
      try {
        const progress = await fetchUserTable(resolvedLearningLang);
        const nextSections = {};
        (Array.isArray(progress) ? progress : []).forEach(item => {
          const wordId = Number(item?.wordId);
          const section = Number(item?.section);
          if (Number.isNaN(wordId) || Number.isNaN(section)) return;
          nextSections[wordId] = Math.max(1, Math.min(5, Math.trunc(section)));
        });
        const has = Array.isArray(progress) && progress.some(item => Number(item.section) >= 3);
        setProgressSections(nextSections);
        setHasRepeatWords(has);
      } catch {
        setProgressSections({});
        setHasRepeatWords(false);
      }
    };
    checkRepeatWords();
  }, [resolvedLearningLang]);

  const themeStats = buildCounts(
    applySectionFilter(applyLevelFilter(applyTypeFilter(linkedItems, selectedTypes), selectedLevels), selectedSections),
    item => item.category || 'Other'
  );

  const typeStats = buildCounts(
    applySectionFilter(applyLevelFilter(applyThemeFilter(linkedItems, selectedThemes), selectedLevels), selectedSections),
    item => item.pos || 'Other'
  );

  const levelStats = buildCounts(
    applySectionFilter(applyTypeFilter(applyThemeFilter(linkedItems, selectedThemes), selectedTypes), selectedSections),
    item => item.level || 'other'
  );

  const sectionStats = buildCounts(
    applyLevelFilter(applyTypeFilter(applyThemeFilter(linkedItems, selectedThemes), selectedTypes), selectedLevels),
    item => resolveItemSection(item)
  );

  const sortedThemes = Object.entries(themeStats)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([theme, count]) => ({ theme, count }));

  const sortedTypes = Object.entries(typeStats)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([type, count]) => ({ type, count }));

  const sortedLevels = levelOptions
    .filter(level => (levelStats[level] || 0) > 0)
    .map(level => ({ level, count: levelStats[level] || 0 }));

  const sortedSections = sectionOptions
    .filter(section => (sectionStats[section] || 0) > 0)
    .map(section => ({ section, count: sectionStats[section] || 0 }));

  const totalWords = Object.values(themeStats).reduce((sum, count) => sum + count, 0);
  const totalTypeWords = Object.values(typeStats).reduce((sum, count) => sum + count, 0);
  const totalLevelWords = Object.values(levelStats).reduce((sum, count) => sum + count, 0);
  const totalSectionWords = Object.values(sectionStats).reduce((sum, count) => sum + count, 0);
  const fullyFilteredItems = applySectionFilter(
    applyLevelFilter(
      applyTypeFilter(applyThemeFilter(linkedItems, selectedThemes), selectedTypes),
      selectedLevels
    ),
    selectedSections
  );
  const modeSectionsMap = {
    repeat: [3, 4, 5],
    learn: [1, 2, 3],
    mix: [1, 2, 3, 4, 5]
  };
  const hasWordsForMode = (mode) => fullyFilteredItems.some(item => {
    const itemSection = Number(resolveItemSection(item)) || 1;
    return modeSectionsMap[mode].includes(itemSection);
  });
  const isRepeatEnabled = hasRepeatWords && hasWordsForMode('repeat');
  const isLearnEnabled = hasWordsForMode('learn');
  const isMixEnabled = hasWordsForMode('mix');

  const toggleTheme = (theme) => {
    const newSelected = new Set(selectedThemes);
    if (newSelected.has(theme)) {
      newSelected.delete(theme);
    } else {
      newSelected.add(theme);
    }
    setSelectedThemes(newSelected);
  };

  const toggleType = (type) => {
    const newSelected = new Set(selectedTypes);
    if (newSelected.has(type)) {
      newSelected.delete(type);
    } else {
      newSelected.add(type);
    }
    setSelectedTypes(newSelected);
  };

  const toggleLevel = (level) => {
    const nextSelected = new Set(selectedLevels);
    if (nextSelected.has(level)) {
      nextSelected.delete(level);
    } else {
      nextSelected.add(level);
    }
    setSelectedLevels(nextSelected);
  };

  const toggleSection = (section) => {
    const nextSelected = new Set(selectedSections);
    if (nextSelected.has(section)) {
      nextSelected.delete(section);
    } else {
      nextSelected.add(section);
    }
    setSelectedSections(nextSelected);
  };

  const selectAllThemes = () => {
    if (selectedThemes.size === sortedThemes.length) {
      setSelectedThemes(new Set());
    } else {
      setSelectedThemes(new Set(sortedThemes.map(t => t.theme)));
    }
  };

  const selectAllTypes = () => {
    if (selectedTypes.size === sortedTypes.length) {
      setSelectedTypes(new Set());
    } else {
      setSelectedTypes(new Set(sortedTypes.map(t => t.type)));
    }
  };

  const selectAllLevels = () => {
    if (selectedLevels.size === sortedLevels.length) {
      setSelectedLevels(new Set());
    } else {
      setSelectedLevels(new Set(sortedLevels.map(item => item.level)));
    }
  };

  const selectAllSections = () => {
    if (selectedSections.size === sortedSections.length) {
      setSelectedSections(new Set());
    } else {
      setSelectedSections(new Set(sortedSections.map(item => item.section)));
    }
  };

  const themeVars = getLanguageCssVars(resolvedLearningLang || uiLang);

  return (
    <div className="cards-menu-container" style={themeVars}>
      <button 
        className="cards-menu-back-button" 
        onClick={() => {
          // Очищаем сохраненные темы при выходе в MainMenu
          localStorage.removeItem('cardsMenuSelectedThemes');
          localStorage.removeItem('cardsMenuSelectedTypes');
          localStorage.removeItem('cardsMenuSelectedLevels');
          localStorage.removeItem('cardsMenuSelectedSections');
          localStorage.removeItem('cardsMenuSelectedLevel');
          localStorage.removeItem('cardsMenuSelectedSection');
          onBack();
        }}
      >
        {t('back', uiLang)}
      </button>
      
      <div className="cards-menu-filters">
        <div className="cards-menu-themes-selector">
          <button
            className="cards-menu-themes-toggle"
            onClick={() => {
              setIsDropdownOpen(!isDropdownOpen);
              setIsTypesDropdownOpen(false);
              setIsLevelsDropdownOpen(false);
              setIsSectionsDropdownOpen(false);
            }}
          >
            {t('selectTopics', uiLang)} {selectedThemes.size > 0 ? `(${selectedThemes.size})` : ''} ▼
          </button>
          {isDropdownOpen && (
            <div className="cards-menu-themes-dropdown">
              {sortedThemes.length > 0 ? (
                <>
                  <div
                    className={`cards-menu-theme-item cards-menu-theme-all ${selectedThemes.size === sortedThemes.length ? 'active' : ''}`}
                    onClick={selectAllThemes}
                  >
                    <input
                      type="checkbox"
                      checked={selectedThemes.size === sortedThemes.length && sortedThemes.length > 0}
                      onChange={() => {}}
                      className="cards-menu-theme-checkbox"
                    />
                    {t('allTopics', uiLang, { count: totalWords, word: wordCountLabel(totalWords, uiLang) })}
                  </div>
                  {sortedThemes.map(({ theme, count }) => (
                    <div
                      key={theme}
                      className={`cards-menu-theme-item ${selectedThemes.has(theme) ? 'active' : ''}`}
                      onClick={() => toggleTheme(theme)}
                    >
                      <input
                        type="checkbox"
                        checked={selectedThemes.has(theme)}
                        onChange={() => {}}
                        className="cards-menu-theme-checkbox"
                      />
                      {tCategory(theme, uiLang)}: {count} {wordCountLabel(count, uiLang)}
                    </div>
                  ))}
                </>
              ) : (
                <div className="cards-menu-theme-item">{t('noTopics', uiLang)}</div>
              )}
            </div>
          )}
        </div>

        <div className="cards-menu-themes-selector">
          <button
            className="cards-menu-themes-toggle"
            onClick={() => {
              setIsTypesDropdownOpen(!isTypesDropdownOpen);
              setIsDropdownOpen(false);
              setIsLevelsDropdownOpen(false);
              setIsSectionsDropdownOpen(false);
            }}
          >
            {t('selectTypes', uiLang)} {selectedTypes.size > 0 ? `(${selectedTypes.size})` : ''} ▼
          </button>
          {isTypesDropdownOpen && (
            <div className="cards-menu-themes-dropdown">
              {sortedTypes.length > 0 ? (
                <>
                  <div
                    className={`cards-menu-theme-item cards-menu-theme-all ${selectedTypes.size === sortedTypes.length ? 'active' : ''}`}
                    onClick={selectAllTypes}
                  >
                    <input
                      type="checkbox"
                      checked={selectedTypes.size === sortedTypes.length && sortedTypes.length > 0}
                      onChange={() => {}}
                      className="cards-menu-theme-checkbox"
                    />
                    {t('allTypes', uiLang, { count: totalTypeWords, word: wordCountLabel(totalTypeWords, uiLang) })}
                  </div>
                  {sortedTypes.map(({ type, count }) => (
                    <div
                      key={type}
                      className={`cards-menu-theme-item ${selectedTypes.has(type) ? 'active' : ''}`}
                      onClick={() => toggleType(type)}
                    >
                      <input
                        type="checkbox"
                        checked={selectedTypes.has(type)}
                        onChange={() => {}}
                        className="cards-menu-theme-checkbox"
                      />
                      {tPos(type, uiLang)}: {count} {wordCountLabel(count, uiLang)}
                    </div>
                  ))}
                </>
              ) : (
                <div className="cards-menu-theme-item">{t('noTypes', uiLang)}</div>
              )}
            </div>
          )}
        </div>

        <div className="cards-menu-themes-selector">
          <button
            className="cards-menu-themes-toggle"
            onClick={() => {
              setIsLevelsDropdownOpen(!isLevelsDropdownOpen);
              setIsDropdownOpen(false);
              setIsTypesDropdownOpen(false);
              setIsSectionsDropdownOpen(false);
            }}
          >
            {t('selectLevels', uiLang)} {selectedLevels.size > 0 ? `(${selectedLevels.size})` : ''} ▼
          </button>
          {isLevelsDropdownOpen && (
            <div className="cards-menu-themes-dropdown">
              <div
                className={`cards-menu-theme-item cards-menu-theme-all ${selectedLevels.size === sortedLevels.length ? 'active' : ''}`}
                onClick={selectAllLevels}
              >
                <input
                  type="checkbox"
                  checked={selectedLevels.size === sortedLevels.length && sortedLevels.length > 0}
                  onChange={() => {}}
                  className="cards-menu-theme-checkbox"
                />
                {t('allLabel', uiLang)}: {totalLevelWords} {wordCountLabel(totalLevelWords, uiLang)}
              </div>
              {sortedLevels.map(({ level, count }) => (
                <div
                  key={level}
                  className={`cards-menu-theme-item ${selectedLevels.has(level) ? 'active' : ''}`}
                  onClick={() => toggleLevel(level)}
                >
                  <input
                    type="checkbox"
                    checked={selectedLevels.has(level)}
                    onChange={() => {}}
                    className="cards-menu-theme-checkbox"
                  />
                  {level}: {count} {wordCountLabel(count, uiLang)}
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="cards-menu-themes-selector">
          <button
            className="cards-menu-themes-toggle"
            onClick={() => {
              setIsSectionsDropdownOpen(!isSectionsDropdownOpen);
              setIsDropdownOpen(false);
              setIsTypesDropdownOpen(false);
              setIsLevelsDropdownOpen(false);
            }}
          >
            {t('selectSections', uiLang)} {selectedSections.size > 0 ? `(${selectedSections.size})` : ''} ▼
          </button>
          {isSectionsDropdownOpen && (
            <div className="cards-menu-themes-dropdown">
              <div
                className={`cards-menu-theme-item cards-menu-theme-all ${selectedSections.size === sortedSections.length ? 'active' : ''}`}
                onClick={selectAllSections}
              >
                <input
                  type="checkbox"
                  checked={selectedSections.size === sortedSections.length && sortedSections.length > 0}
                  onChange={() => {}}
                  className="cards-menu-theme-checkbox"
                />
                {t('allLabel', uiLang)}: {totalSectionWords} {wordCountLabel(totalSectionWords, uiLang)}
              </div>
              {sortedSections.map(({ section, count }) => (
                <div
                  key={section}
                  className={`cards-menu-theme-item ${selectedSections.has(section) ? 'active' : ''}`}
                  onClick={() => toggleSection(section)}
                >
                  <input
                    type="checkbox"
                    checked={selectedSections.has(section)}
                    onChange={() => {}}
                    className="cards-menu-theme-checkbox"
                  />
                  {section}: {count} {wordCountLabel(count, uiLang)}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
      
      <h1 className="cards-menu-title">{t('chooseMode', uiLang)}</h1>
      <div className="cards-menu-actions">
        <button 
          className={`cards-menu-button ${!isRepeatEnabled ? 'cards-menu-button--disabled' : ''}`}
          onClick={() => isRepeatEnabled && onSelectMode('repeat', Array.from(selectedThemes), Array.from(selectedTypes), Array.from(selectedLevels), Array.from(selectedSections))}
          disabled={!isRepeatEnabled}
        >
          {t('repeat', uiLang)}
        </button>
        <button
          className={`cards-menu-button ${!isLearnEnabled ? 'cards-menu-button--disabled' : ''}`}
          onClick={() => isLearnEnabled && onSelectMode('learn', Array.from(selectedThemes), Array.from(selectedTypes), Array.from(selectedLevels), Array.from(selectedSections))}
          disabled={!isLearnEnabled}
        >
          {t('learn', uiLang)}
        </button>
        <button
          className={`cards-menu-button ${!isMixEnabled ? 'cards-menu-button--disabled' : ''}`}
          onClick={() => isMixEnabled && onSelectMode('mix', Array.from(selectedThemes), Array.from(selectedTypes), Array.from(selectedLevels), Array.from(selectedSections))}
          disabled={!isMixEnabled}
        >
          {t('mix', uiLang)}
        </button>
      </div>
      <button
        className="cards-menu-methodology-button"
        onClick={() => setIsMethodologyOpen(true)}
      >
        О методике 5 секций
      </button>
      <div className="cards-menu-hint">
        <div>{t('repeatHint', uiLang)}</div>
        <div>{t('learnHint', uiLang)}</div>
        <div>{t('mixHint', uiLang)}</div>
      </div>

      <FiveSectionsInfo
        isOpen={isMethodologyOpen}
        onClose={() => setIsMethodologyOpen(false)}
        uiLang={uiLang}
      />

    </div>
  );
};

export default CardsMenu;
